/bin/bash -lc "python - <<'PY'
import requests, collections, math, time
base='https://www.ebi.ac.uk/gwas/rest/api'
study_cache={}
def get_study_by_link(href):
    if href not in study_cache:
        u=href.replace('{?projection}','')
        rr=requests.get(u, headers={'Accept':'application/json'}, timeout=30)
        if rr.status_code"'!=200:
            print('"'study fail', rr.status_code, u, rr.text[:100]); return {}
        study_cache[href]=rr.json()
    return study_cache[href]
for rs,target in [('rs72717048',9.31382e-23),('rs144126567',1.07244e-22),('rs1150756',4.85572e-19)]:
    r=requests.get(f'{base}/singleNucleotidePolymorphisms/{rs}/associations', params={'projection':'associationBySnp','size':200}, headers={'Accept':'application/json'}, timeout=30)
    print('\\nREQ', rs, r.status_code, r.url)
    data=r.json()
    assocs=data.get('_embedded',{}).get('associations',[])
    rows=[]
    for a in assocs:
        p=a.get('pvalue')
        if p is None and a.get('pvalueMantissa') is not None:
            p=a['pvalueMantissa']*10**a['pvalueExponent']
        st=pm=trait=title=None
        href=a.get('_links',{}).get('study',{}).get('href')
        if href:
